   "answer": "A",
   "analysis": "本题考查时政常识。\n2013年习近平总书记在圣彼得堡会见默克尔时表示，总理女士是物理学博士，我由“牛顿力学三定律”联想到如何更好推动中德关系发展。一是牢牢把握中德合作的“惯性”。合作是中德关系的主旋律和大方向，双方要坚持不动摇。要继续加强高层交往，用好政府磋商、战略对话等机制，不断提升战略互信；二是通过深化务实合作提升中德关系的“加速度”。中国正在以改革促调整，以调整促发展。我们有信心实现经济持续健康发展，为中德合作提供更多机遇。两国要强化伙伴和机遇意识，本着互利双赢、共同发展的精神，不断扩大利益交融，全面深化务实合作；三是减少两国关系发展的“反作用力”。双方要着眼共同利益，求大同，存小异，减少两国关系发展的阻力。故A项正确，B、C、D选项错误。\n故正确答案为A。",
   "exam": "jilin",
   "year": 2018
