   "question": "2022年，按照以习近平同志为核心的党中央的部署要求，为稳定宏观经济大盘，稳定上亿市场主体，各部门多措并举优化和落实助企纾困政策，为经济平稳运行提供有力支撑。下列属于“稳主体”对策的是：\n①实施大规模留抵退税政策\n②对特困行业实行阶段性缓缴养老保险费\n③中国人民银行宣布下调金融机构存款准备金率\n④设立3岁以下婴幼儿照护个人所得税专项附加扣除\n⑤央行、银保监会发布个人首套房商贷利率下限调整",
