   "source": "2024年吉林省公务员录用考试《行测》题 · 第6题",
   "question": "2023年中央经济工作会议将深化重点领域改革列为2024年重点工作之一，下列关于深化重点领域改革的系列举措不符合中央经济工作会议措施的是：",
