   "source": "2026年吉林省公务员录用考试《行测》题 · 第2题",
   "question": "加强数字政府建设是创新政府治理理念和方式、形成数字治理新格局、推进国家治理体系和治理能力现代化的重要举措。下列关于数字政府建设的基本原则，表述正确的有几项?\n①坚持党的全面领导，充分发挥党总揽全局、协调各方的领导核心作用\n②坚持以市场为中心，始终把满足人民群众物质生活的迫切需求作为目标\n③坚持整体协同，强化系统观念，加强系统集成，全面提升数字政府集约化建设水平\n④坚持数据赋能，建立健全数据治理制度和标准体系，加强数据汇聚融合、共享开放和开发利用",
   "options": [
    "A. 1项",
    "B. 2项",
    "C. 3项",
    "D. 4项"
   ],
   "answer": "C",
   "analysis": "本题考查新思想。\n2022年6月23日，国务院发布了《关于加强数字政府建设的指导意见》，以下简称《意见》。\n①正确，《意见》“一、发展现状和总体要求”中“2.基本原则”部分指出：“坚持党的全面领导。充分发挥党总揽全局、协调各方的领导核心作用，全面贯彻党中央、国务院重大决策部署，将坚持和加强党的全面领导贯穿数字政府建设各领域各环节，贯穿政府数字化改革和制度创新全过程，确保数字政府建设正确方向。”\n②错误，《意见》“一、发展现状和总体要求”中“2.基本原则”部分指出：“坚持以人民为中心。始终把满足人民对美好生活的向往作为数字政府建设的出发点和落脚点······”故“以市场为中心，始终把满足人民群众物质生活的迫切需求作为目标”说法错误，应为“以人民为中心，始终把满足人民对美好生活的向往作为数字政府建设的出发点和落脚点”\n③正确，《意见》“一、发展现状和总体要求”中“2.基本原则”部分指出：“坚持整体协同。强化系统观念，加强系统集成，全面提升数字政府集约化建设水平，统筹推进技术融合、业务融合、数据融合，提升跨层级、跨地域、跨系统、跨部门、跨业务的协同管理和服务水平······”\n④正确，《意见》“一、发展现状和总体要求”中“2.基本原则”部分指出：“坚持数据赋能。建立健全数据治理制度和标准体系，加强数据汇聚融合、共享开放和开发利用，促进数据依法有序流动，充分发挥数据的基础资源作用和创新引擎作用，提高政府决策科学化水平和管理服务效率，催生经济社会发展新动能。”\n故①③④正确，共3项。\n故正确答案为C。",
   "exam": "jilin",
   "year": 2026
