   "source": "2026年吉林省公务员录用考试《行测》题 · 第4题",
   "question": "习近平总书记指出，讲好中国故事，传播好中国声音，展示真实、立体、全面的中国，是加强我国国际传播能力建设的重要任务。关于加强我国国际传播能力建设，下列表述正确的是：\n①要提升国际传播体系稳定性，防范国际传播格局重构\n②要全面提升国际传播效能，建强适应新时代国际传播需要的专门人才队伍\n③要倡导和平的国际舆论环境，不参与国际舆论斗争，塑造谦逊谦和的大国形象\n④推动走出去、请进来管理便利化，扩大国际人文交流合作",
