   "question": "习近平总书记曾说：“我们要有钉钉子的精神，钉钉子往往不是一锤子就能钉好的，而是要一锤一锤接着敲，直到把钉子钉实钉牢，钉牢一颗再钉下一颗，不断钉下去，必然大有成效。如果东一榔头西一棒子，结果很可能是一颗钉子都钉不上、钉不牢。”这句话最能体现的哲学原理是：\n①量变与质变辩证统一\n②肯定与否定辩证统一\n③主要矛盾与次要矛盾辩证统一\n④尊重客观规律与发挥主观能动性辩证统一",
