   "analysis": "本题考查物理常识。\nB项不符合题意：饮料本来依附在瓶子上，瓶子破裂，饮料与瓶子之间的附着力消失，饮料因自身惯性脱离原位溅出，体现的是惯性原理，与“大质量恒星末期爆炸”的机理并不对应，故B项当选（选非）。大质量恒星的质量越大，引力越大，塌陷时的压力就越强，大质量恒星末期爆炸是由于引力与塌陷产生的压力不平衡造成的。\nA项不符合题意：两种现象均体现压强原理，高压锅蒸煮食物利用压强提高沸点，火星上由于气压低，水的沸点也降低。\nC项不符合题意：两种现象都是由于膨胀造成周围物质远移。天体物理学家经常用“葡萄干面包”来比喻宇宙扩张。\nD项不符合题意：两种现象均体现了光的散射原理。\n本题为选非题，故正确答案为B。",
