   "question": "A县某酒厂酿造的“仙液”系列白酒深为当地人喜爱，A县政府办公室发文指定该酒为“接待用酒”，要求各机关、企事业单位、社会团体在业务用餐时，饮酒应以“仙液”系列为主，同时，酒厂公开承诺用餐者凭市内各酒楼出具的证明，可以取得消费100元返还10元的奖励。关于此事，下列说法错误的是：",
