   "question": "翻开古代诗词，你可以一一品味诗人们深切的思想感情。读王维、孟浩然，你懂得了什么是钟情山水；读杜甫、白居易，你懂得了什么是忧民情结；读辛弃疾、陆游，你懂得了什么是爱国情怀，这段话体现的哲理是：",
