   "source": "2017年422联考《行测》题（吉林卷甲级） · 第3题",
   "question": "积极者说，人生犹如一首歌，有低音也有高调，抑扬顿挫是人生美妙的旋律；消极者说，人生犹如一场戏，有高潮也有低潮，喜怒哀乐是人生无奈的节奏。这段话反映的哲理是：",
