   "source": "2017年422联考《行测》题（吉林卷甲级） · 第6题",
   "question": "九是中国古代最高统治者的专属数字。西周时期，只有天子可用九鼎，后世只有皇帝的龙袍可绣九条金龙。与此直接相关的制度是：",
