   "answer": "D",
   "analysis": "本题主要考查文化常识。“五味”属于中药学概念，五味理论最早载于《神农本草经》，其序录云：“药有酸、咸、甘、苦、辛五味，又有寒、热、温、凉四气。”中药学中根据中药的味道、作用将其概括为酸、苦、甘、辛、咸，题干中的甜属于甘，辣属于辛，随症用药对五脏（心、肝、脾、肺、肾）有一定的选择性，《素问·宣明五气论》中有：“酸入肝、苦入心、甘入脾、辛入肺、咸入肾”之说。其作用是辛味药以散肺气之郁，甘味药以补脾气之虚，苦味药以泻心火，酸味药以敛肝阴，咸味药以补肾虚。所以五味与“五脏”对应关系是：酸对应肝脏，苦对应心脏，甜（甘）对应脾脏，辣（辛）对应肺脏，咸对应肾脏。 \nA、B、C三项正确，酸对应肝脏，甜（甘）对应脾脏，咸对应肾脏。\nD项错误，辣（辛）对应肺脏，而不是心脏，心脏对应苦味。\n本题为选非题，故正确答案为D。",
