   "question": "中国桥的历史悠久，发展于隋，兴盛于宋。下列描述所指的中国四大名桥依次是\n①世界上最早的启闭式桥梁\n②我国现存年代最早的梁式大石桥\n③北京市现存最古老的石造联拱桥\n④世界上现存最完整的最早单孔石拱桥",
