   "analysis": "本题考查人文常识。\n“雏既壮而能飞兮，乃衔食而反哺。”出自《初学记·鸟赋》，源自典故“乌鸦反哺”，意思指：乌雏长成，衔食喂养其母。后比喻报答亲恩。句中所描写的鸟指乌鸦。 \n故正确答案为D。",
   "exam": "jilin",
   "year": 2019
