   "question": "近年来，我国面临的农业安全复杂性不断增加。下列关于农业安全的说法不正确的是：",
   "options": [
    "A. 为确保我国粮食安全，多部门制定了《沙漠蝗及国内蝗虫监测防控预案》，要求各地严防境外沙漠蝗入侵危害，继续做好国内蝗虫防治工作",
    "B. 生物安全三级实验室需要从事某种高致病性动物病原微生物实验活动的，需要报省级以上畜牧兽医主管部门批准",
    "C. 根据现行规定，举报为防控非洲猪瘟作出特别重大贡献的，可一次性给予举报人10万元奖励",
    "D. 2020年是我国第三次全国农作物种质资源普查与收集行动的收官之年"
   ],
   "answer": "C",
   "analysis": "本题考查政治常识。\nA项正确，2020年3月6日，农业农村部、海关总署、国家林草局印发了《沙漠蝗及国内蝗虫监测防控预案》的通知：总体目标是“两个努力确保”，努力确保境外沙漠蝗不迁入造成危害，努力确保国内蝗虫不暴发成灾，全力夺取小康之年粮食丰收，有效保障生态安全。\nB项正确，2020年2月28日，农业农村部、教育部等七部门联合发布《关于加强动物病原微生物实验室生物安全管理工作的通知》，通知要求，加强动物病原微生物实验活动监管，生物安全三级、四级实验室需要从事某种高致病性动物病原微生物或者疑似高致病性动物病原微生物实验活动的，应报省级以上畜牧兽医主管部门批准。\nC项错误，2019年11月22日，农业农村部近日印发的《非洲猪瘟疫情有奖举报暂行办法》中提出，“奖励标准。由农业农村部受理经查证属实并符合奖励原则的举报，农业农村部给予举报人每次3000—10000元（税前）不等的奖励。具体的奖励标准另行规定。举报为防控非洲猪瘟作出特别重大贡献的，可一次性给予举报人高于前款规定标准并不超过30000元（税前）的奖励。”\nD项正确，2015年7月9日，《农业部办公厅关于印发<第三次全国农作物种质资源普查与收集行动实施方案>的通知》指出，第三次全国农作物种质资源普查与收集的实施期限为2015年1月1日至2020年12月31日，所以2020年就是收官之年。\n本题为选非题，故正确答案为C。",
