   "analysis": "本题考查人文常识。东北地区，简称东北，指辽宁省、吉林省、黑龙江省三省以及内蒙古东五盟市区域。\nA项正确，庙后山位于辽宁本溪县山城子镇山城子村，是一处古人类文化遗址。庙后山遗址中发掘的火塘遗址附近出土了大量大型动物的焦炭化碎骨。这表明庙后山古人类已掌握了用火烤肉和敲骨吸髓的食用方法，是人类踏入文明的重要标志。\nB项错误，后城咀石城址位于内蒙古自治区呼和浩特市清水河县宏河镇后城咀村，占地约138万平方米，拥有较为完备的瓮城、壕沟、城门、马面、瞭望台等防御体系。经专家考证，距今约4200～4500年（据最近C14测年结果），是目前内蒙古中南部发现等级最高、规模最大的龙山时代石城址。该遗址不属于东北地区。\nC项正确，契丹文八角铜镜，1971年在吉林省大安县红岗出土，是吉林省博物院收藏的十大国宝之一。这面铜镜有边款阴刻7个汉字“济州录事完颜通”，镜背铸契丹小字五行，契丹文的四周有对称的两组花纹，是中原地区常用的缠枝纹。\nD项正确，金上京城，即金上京会宁府遗址，是金王朝修筑的第一座都城，也是金代早期的政治、经济、文化中心，遗址位于黑龙江省哈尔滨市阿城区南2公里阿什河左岸。金上京会宁府遗址南北二城的城垣和皇城内的建筑址保存较好，皇城南门至南城南墙西门址之间，有一条宽40余米的大道，其与皇城内殿址处于一条轴线上。\n本题为选非题，故正确答案为B。",
