   "analysis": "本题考查科技常识。\nA项正确，雷达生命探测仪是集雷达技术、生物医学工程技术于一体的生命探测设备，主要利用电磁波的反射原理制成，通过检测人体生命活动所引起的各种微动，从这些微动中得到呼吸、心跳的有关信息，从而辨识有无生命。雷达生命探测仪主动探测的方式使其不易受到温度、湿度、噪声、现场地形等因素的影响，并且电磁波的性质也使它增加了侦测的范围。可以说，这是目前世界上最先进的生命探测仪。\nB项错误，光学生命探测仪，主要解决在能见度不良，具有一定间隙的条件下，遇难者的搜寻问题。这类仪器是把物体发射或反射的光辐射转换成电信号，经信号处理，再现物体的图像，达到搜救的目的，但是在没有间隙的情况下探测有难度。\nC项错误，音频生命探测仪应用了声波的原理，可探测以空气为载体的各种声波和以其他媒体为载体的振动，进而迅速确定被困者的位置。但是，由于音频生命探测仪是一种被动接收音频信号和振动信号的仪器，救援时需要在废墟中寻找空隙伸入探头，容易受到现场噪声的影响，而且探测速度较慢。\nD项错误，任何物体只要温度在绝对零度以上都会产生红外辐射，人体也是天然的红外辐射源。但是，由于人的体核温度以及体表各部位温度的不同，人体的红外辐射特性与周围环境的红外辐射特性就会有差异。红外生命探测仪就是利用这一原理，以成像的方式把地震废墟中的受困者与背景环境分开，从而让搜救人员找到受困者。但是，由于红外辐射是一种长波辐射，能量小，穿透力强，很容易被一般的物质所吸收，这就导致了红外生命探测仪的探测范围存在局限。如果受困者被红外吸收能力较强的物体所掩埋或者掩埋较深，很可能就无法被探测到。\n故正确答案为A。",
