   "analysis": "本题考查科技常识。\nA项正确，灰色镜片对太阳光中各色光的过滤量几乎相等，可完全吸收红外线和98%的紫外线。它最大的好处是不会使景物原来的颜色因镜片而改变，而且可以非常有效地降低光线强度。\nB项错误，黄色镜片可吸收100%的紫外线，并且能让红外线和83%的可见光穿透镜片。黄色镜片最大的特点在于吸收了大部分的蓝光。黄色镜片吸收了蓝光以后，可以使自然界的景物更清楚，因此常用来当作“滤光镜”，适用于清晨、黄昏或是雨天的光线环境。\nC项错误，茶色镜片能滤除大量蓝光，可以改善视觉的对比度和清晰度，适合在空气污染严重或者多雾的情况下佩戴。\nD项错误，和灰色镜片一样，绿色镜片也可以有效地吸收红外线和98%的紫外线。但是，绿色镜片同时也阻挡了光线中的青、红色，导致人所看到的景物颜色有时会发生改变，而且其阻隔光线的效果也要略低于灰色镜片。\n故正确答案为A。",
